logic.script:
		gui.addChangeCommand("svydesign_object6.available", "update_root6()");
      function update_root6() {
         var obj = gui.getValue("svydesign_object6.available");
         if (obj !== "") {
            gui.setValue("svydesign_selector6.root", obj + "$variables");
         } else {
            gui.setValue("svydesign_selector6.root", "");
         }
      }
